65	    const next = nextGeneration([[1, 0], [2, 1], [0, 2], [1, 2], [2, 2]]);
66	
67	    const ordered = asCellSet(next);
68	    const duplicates = ordered.filter(([x, y], index) => {
69	      const previous = ordered[index - 1];
70	      return previous !== undefined && previous[0] === x && previous[1] === y;
